import 'package:flutter/material.dart';
import '../app_state.dart';
import '../domain/models.dart';
import '../services/location_service.dart';
import 'map_screen.dart';

class PrepareRouteScreen extends StatelessWidget{
 final AppState state; const PrepareRouteScreen({super.key,required this.state});
 bool _routeActive(DeliveryPackage p)=>p.status==DeliveryStatus.pending||p.status==DeliveryStatus.current||p.status==DeliveryStatus.absent||p.status==DeliveryStatus.addressProblem;
 Future<void> _locate(BuildContext c)async{if(state.reviewCount>0){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Revise ${state.reviewCount} endereço${state.reviewCount==1?'':'s'} antes de preparar a rota.')));return;}await state.locateConfirmed();if(!c.mounted)return;final failed=state.lastLocateFailed;ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(failed==0?'${state.lastLocateSucceeded} endereço${state.lastLocateSucceeded==1?'':'s'} localizado${state.lastLocateSucceeded==1?'':'s'} com sucesso.':'${state.lastLocateSucceeded} localizado${state.lastLocateSucceeded==1?'':'s'} • $failed não localizado${failed==1?'':'s'}. Confira os endereços e tente novamente.')));}
 Future<void> _acceptApproximate(BuildContext c,DeliveryPackage package)async{final index=state.packages.indexWhere((p)=>p.id==package.id);if(index<0)return;final accepted=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('⚠️ Localização aproximada'),content:Text('Não conseguimos confirmar o número ${package.address.number??'informado'}, mas encontramos ${package.address.street??'a rua'}.\n\nAo continuar, a navegação levará você até um ponto aproximado dessa rua. O endereço original será mantido.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('ACEITAR E IR ATÉ A RUA'))]));if(accepted==true){await state.acceptApproximate(index);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Localização aproximada aceita.')));}}
 Future<void> _optimize(BuildContext c)async{try{final p=await LocationService().current();await state.optimizeFrom(p.latitude,p.longitude);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Rota otimizada a partir da sua posição.')));}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('$e')));}}
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:state,builder:(context,_){
   final activePackages=state.packages.where(_routeActive).toList();final active=activePackages.length;final located=activePackages.where((p)=>p.address.latitude!=null&&p.address.longitude!=null).length;final unresolved=active-located;final review=activePackages.where((p)=>p.address.validation!=ValidationStatus.confirmed).length;final approximate=activePackages.where((p)=>p.address.isApproximate&&!p.address.approximateAccepted).toList();final allReady=active>0&&review==0&&unresolved==0&&approximate.isEmpty;final canLocate=review==0&&unresolved>0;final canOptimize=allReady&&active>=2;final canMap=allReady&&(active==1||state.routeOptimized);final progress=active==0?0.0:(located/active).clamp(0.0,1.0);final nextStep=active==0?'Adicione ou escaneie os pacotes da rota.':review>0?'Revise os $review endereço${review==1?'':'s'} com alerta.':unresolved>0?'Localize os $unresolved endereço${unresolved==1?'':'s'} restante${unresolved==1?'':'s'}.':approximate.isNotEmpty?'Confirme ${approximate.length} localização${approximate.length==1?' aproximada':'ões aproximadas'} antes de seguir.':active>1&&!state.routeOptimized?'Todos localizados. Agora otimize a ordem das entregas.':'Rota pronta. Confira o mapa antes de seguir.';
   return Scaffold(appBar:AppBar(title:const Text('Preparar rota')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$active pacotes ativos',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:4),Text('$review precisam de revisão • $located de $active localizados'),const SizedBox(height:12),LinearProgressIndicator(value:progress),const SizedBox(height:8),Text(nextStep,style:const TextStyle(fontWeight:FontWeight.w600)),if(unresolved>0)Padding(padding:const EdgeInsets.only(top:6),child:Text('$unresolved ainda não ${unresolved==1?'foi localizado':'foram localizados'}',style:TextStyle(color:Theme.of(context).colorScheme.error,fontWeight:FontWeight.w600))),if(state.lastLocateFailed>0&&!state.locating)Padding(padding:const EdgeInsets.only(top:8),child:Container(width:double.infinity,padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:Theme.of(context).colorScheme.errorContainer,borderRadius:BorderRadius.circular(10)),child:Text('Última tentativa: ${state.lastLocateAttempted} consultados • ${state.lastLocateSucceeded} encontrados • ${state.lastLocateFailed} falharam.'))),if(state.routeOptimized&&allReady&&active>1)const Padding(padding:EdgeInsets.only(top:6),child:Row(children:[Icon(Icons.check_circle_outline,size:18),SizedBox(width:6),Text('Rota otimizada e pronta')])),if(state.locating)...[const SizedBox(height:10),const LinearProgressIndicator(),const SizedBox(height:6),Text('Localizando... ${state.lastLocateSucceeded+state.lastLocateFailed} de ${state.lastLocateAttempted} processados')]]))),const SizedBox(height:12),if(approximate.isNotEmpty)...[for(final p in approximate)Card(color:Theme.of(context).colorScheme.errorContainer,child:ListTile(leading:const Icon(Icons.warning_amber_rounded),title:const Text('Número não confirmado',style:TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${p.address.street??p.address.raw}, nº ${p.address.number??'?' }'),trailing:FilledButton(onPressed:()=>_acceptApproximate(context,p),child:const Text('ACEITAR')))),const SizedBox(height:10)],if(unresolved>0)FilledButton.icon(onPressed:state.locating||!canLocate?null:()=>_locate(context),icon:const Icon(Icons.location_searching),label:const Padding(padding:EdgeInsets.all(14),child:Text('LOCALIZAR PENDENTES'))),if(unresolved>0)const SizedBox(height:10),FilledButton.tonalIcon(onPressed:canOptimize?()=>_optimize(context):null,icon:Icon(state.routeOptimized?Icons.check_circle:Icons.route),label:Padding(padding:const EdgeInsets.all(14),child:Text(state.routeOptimized?'ROTA OTIMIZADA • REOTIMIZAR':'OTIMIZAR ROTA'))),const SizedBox(height:10),FilledButton.icon(onPressed:canMap?()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>RouteMapScreen(state:state))):null,icon:const Icon(Icons.map_outlined),label:const Padding(padding:EdgeInsets.all(16),child:Text('CONFERIR ROTA NO MAPA'))),if(review>0)const Padding(padding:EdgeInsets.only(top:10),child:Text('Confirme os endereços marcados com ⚠️ antes de preparar a rota.',textAlign:TextAlign.center))else if(unresolved>0&&!state.locating)Padding(padding:const EdgeInsets.only(top:10),child:Text('Faltam $unresolved endereço${unresolved==1?'':'s'} no mapa. A rota não seguirá deixando pacote para trás.',textAlign:TextAlign.center))else if(active>1&&!state.routeOptimized)const Padding(padding:EdgeInsets.only(top:10),child:Text('Todos os endereços estão localizados. Agora otimize a rota antes de conferir o mapa.',textAlign:TextAlign.center))]));});
}
